Signature: public List<Content> retrieve(Query query)
Body: {
    LAST_SOURCES.remove();
    // For a refactoring, websearch/RAG or context should not be used.
    if (query.text().startsWith("**Do NOT include notes, explanations, or extra text.**") && query.text().contains("Refactor the")) {
        LAST_SOURCES.set(List.of());
        return List.of();
    }
    try {
        CompletableFuture<List<Content>> retrieverFuture = CompletableFuture.completedFuture(Collections.emptyList());
        if (settings.ragEnabled()) {
            retrieverFuture = CompletableFuture.supplyAsync(() -> contentRetriever.retrieve(query), executor);
        }
        CompletableFuture<List<Content>> webSearchFuture = CompletableFuture.completedFuture(Collections.emptyList());
        if (settings.webSearchEnabled()) {
            webSearchFuture = CompletableFuture.supplyAsync(() -> duckDuckGoContentRetriever.retrieve(query), executor);
        }
        CompletableFuture<List<Content>> workspaceFuture = CompletableFuture.supplyAsync(() -> workspaceContextProvider.get().stream().filter(content -> content != null && isRelevant(content) && containsNothing(new ArrayList<>(), content)).toList(), executor);
        CompletableFuture<Void> allDone = CompletableFuture.allOf(retrieverFuture, webSearchFuture, workspaceFuture);
        allDone.get(5000, TimeUnit.SECONDS);
        List<Content> indexResults = safeGet(retrieverFuture);
        List<Content> webResults = safeGet(webSearchFuture);
        List<Content> workspaceResults = safeGet(workspaceFuture);
        List<Content> results = new ArrayList<>(indexResults);
        results.addAll(webResults);
        results.addAll(workspaceResults.stream().filter(content -> containsNothing(results, content)).toList());
        // Capture sources for UI display (readable via popSources() on this thread)
        List<RagSource> ragSources = new ArrayList<>();
        indexResults.forEach(c -> ragSources.add(RagSource.fromContent(c, RagSource.SourceType.INDEX)));
        webResults.forEach(c -> ragSources.add(RagSource.fromContent(c, RagSource.SourceType.WEB)));
        workspaceResults.stream().filter(c -> containsNothing(new ArrayList<>(indexResults), c)).forEach(c -> ragSources.add(RagSource.fromContent(c, RagSource.SourceType.WORKSPACE)));
        LAST_SOURCES.set(ragSources);
        return results;
