Method: fr.baretto.ollamassist.utils.ModelSizeParser#extractParamCountBillions
Signature: public static double extractParamCountBillions(String modelName)
Body: {
    if (modelName == null || modelName.isBlank())
        return -1;
    Matcher m = SIZE_PATTERN.matcher(modelName);
    if (m.find()) {
        try {
            return Double.parseDouble(m.group(1));
        } catch (NumberFormatException ignored) {
            return -1;
        }
    }
    return -1;
}


